BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT json_build_object('kind','tables','rows',coalesce(json_agg(q),'[]'::json)) FROM (SELECT n.nspname schema,r.relname name,r.oid,r.relkind,r.reltuples,r.relpages,r.relrowsecurity,r.relforcerowsecurity,pg_table_size(r.oid) table_bytes,pg_indexes_size(r.oid) index_bytes,pg_total_relation_size(r.oid) total_bytes FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND r.relkind IN ('r','p','m','f') ORDER BY 1,2) q;
SELECT json_build_object('kind','columns','rows',coalesce(json_agg(q),'[]'::json)) FROM (SELECT table_schema,table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,column_default FROM information_schema.columns WHERE table_schema !~ '^pg_' AND table_schema<>'information_schema' ORDER BY 1,2,4) q;
SELECT json_build_object('kind','views','rows',coalesce(json_agg(q),'[]'::json)) FROM (SELECT n.nspname schema,r.relname name,r.relkind,pg_get_viewdef(r.oid,true) definition FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND r.relkind IN ('v','m') ORDER BY 1,2) q;
SELECT json_build_object('kind','functions','rows',coalesce(json_agg(q),'[]'::json)) FROM (SELECT n.nspname schema,p.proname name,pg_get_function_identity_arguments(p.oid) arguments,l.lanname language,p.prosecdef security_definer,p.provolatile volatility,pg_get_functiondef(p.oid) definition,EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e') extension_owned FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND p.prokind IN ('f','p') ORDER BY 1,2,3) q;
SELECT json_build_object('kind','triggers','rows',coalesce(json_agg(q),'[]'::json)) FROM (SELECT n.nspname schema,r.relname table_name,t.tgname name,t.tgenabled enabled,t.tgisinternal internal,pg_get_triggerdef(t.oid,true) definition FROM pg_trigger t JOIN pg_class r ON r.oid=t.tgrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' ORDER BY 1,2,3) q;
SELECT json_build_object('kind','indexes','rows',coalesce(json_agg(q),'[]'::json)) FROM (SELECT n.nspname schema,r.relname table_name,ir.relname name,i.indisprimary,i.indisunique,i.indisvalid,i.indisready,am.amname method,pg_get_indexdef(i.indexrelid) definition,pg_get_expr(i.indpred,i.indrelid) predicate,pg_relation_size(i.indexrelid) bytes,s.idx_scan,s.idx_tup_read,s.idx_tup_fetch FROM pg_index i JOIN pg_class r ON r.oid=i.indrelid JOIN pg_class ir ON ir.oid=i.indexrelid JOIN pg_namespace n ON n.oid=r.relnamespace JOIN pg_am am ON am.oid=ir.relam LEFT JOIN pg_stat_user_indexes s ON s.indexrelid=i.indexrelid WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' ORDER BY 1,2,3) q;
SELECT json_build_object('kind','constraints','rows',coalesce(json_agg(q),'[]'::json)) FROM (SELECT n.nspname schema,r.relname table_name,k.conname name,k.contype type,k.convalidated validated,k.condeferrable deferrable,k.condeferred deferred,k.confdeltype delete_action,k.confmatchtype match_type,pn.nspname parent_schema,pr.relname parent_table,pg_get_constraintdef(k.oid,true) definition,pg_get_expr(k.conbin,k.conrelid) check_expression,ARRAY(SELECT a.attname FROM unnest(k.conkey) WITH ORDINALITY x(num,ord) JOIN pg_attribute a ON a.attrelid=k.conrelid AND a.attnum=x.num ORDER BY x.ord) columns,ARRAY(SELECT a.attname FROM unnest(k.confkey) WITH ORDINALITY x(num,ord) JOIN pg_attribute a ON a.attrelid=k.confrelid AND a.attnum=x.num ORDER BY x.ord) parent_columns,EXISTS(SELECT 1 FROM pg_index i WHERE i.indrelid=k.conrelid AND i.indkey[0]=k.conkey[1]) first_column_index_legacy,EXISTS(SELECT 1 FROM pg_index i WHERE i.indrelid=k.conrelid AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indnkeyatts>=cardinality(k.conkey) AND (SELECT array_agg(v ORDER BY ord) FROM unnest(i.indkey::smallint[]) WITH ORDINALITY z(v,ord) WHERE ord<=cardinality(k.conkey))=k.conkey) full_prefix_index FROM pg_constraint k JOIN pg_namespace n ON n.oid=k.connamespace LEFT JOIN pg_class r ON r.oid=k.conrelid LEFT JOIN pg_class pr ON pr.oid=k.confrelid LEFT JOIN pg_namespace pn ON pn.oid=pr.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' ORDER BY 1,2,3) q;
ROLLBACK;
